function manage_policies($type,$id){
    echo '<div class="card" style="background:var(--bg-secondary);padding:12px;margin-bottom:12px"><label><strong>'.__t('Quick permission setup','تنظیم سریع صلاحیت‌ها','د اجازو چټک تنظیم').'</strong><select class="form-control" name="permission_preset"><option value="custom"'.($id?' selected':'').'>'.__t('Custom choices below','انتخاب دستی در پایین','لاندې خپل انتخاب').'</option><option value="full"'.($id?'':' selected').'>'.__t('All permissions within central ceilings','همهٔ اجازه‌ها در حدود مرکز','ټولې اجازې د مرکز په حد کې').'</option><option value="read_only">'.__t('View and print only','فقط دیدن و چاپ','یوازې کتل او چاپ').'</option><option value="inherit">'.__t('Keep existing / role defaults','حفظ وضعیت موجود یا پیش‌فرض نقش','اوسنی حالت وساتئ').'</option></select></label><small>'.__t('A quick preset replaces the detailed choices below. Central and business locks always remain ceilings.','حالت آماده، انتخاب‌های جزئی پایین را جایگزین می‌کند. قفل‌های مرکز و تجارت همیشه سقف باقی می‌مانند.','چټک انتخاب لاندې انتخابونه بدلوي؛ د مرکز حدونه پاتې دي.').'</small></div>';
    echo '<input name="policy_matrix_started" type="hidden" value="1">';$groups=[];foreach(domain_catalog() as $key=>$label)$groups[explode('.',$key)[0]][$key]=$label;
    foreach($groups as $module=>$features){echo '<details class="policy-group"><summary>'.sanitize(domain_label($module)).'</summary>';
    foreach($features as $key=>$label){$p=$id?domain_policy($type,$id,$key):null;$mode=$p?((int)$p['enabled']?'enabled':($p['visibility']==='hidden'?'hidden':'locked')):($type==='owner_user'?'hidden':'enabled');
        echo '<div class="policy-row"><label>'.sanitize(domain_label($key)).'<select name="policies['.$key.'][mode]" class="form-control"><option value="enabled"'.($mode==='enabled'?' selected':'').'>'.__t('Enabled','باز','خلاص').'</option><option value="locked"'.($mode==='locked'?' selected':'').'>'.__t('Locked but visible','قفل، اما دیده شود','قفل خو ښکاري').'</option><option value="hidden"'.($mode==='hidden'?' selected':'').'>'.__t('Locked and hidden','قفل و پنهان شود','قفل او پټ').'</option></select></label>';
        foreach(['daily_limit'=>__t('Daily limit','حد روزانه','ورځنی حد'),'monthly_limit'=>__t('Monthly limit','حد ماهانه','میاشتنی حد')] as $k=>$l)echo '<label>'.sanitize($l).'<input class="form-control" type="number" min="0" max="1000000" placeholder="∞" name="policies['.$key.']['.$k.']" value="'.sanitize($p[$k]??'').'"></label>';
        echo '</div>';
    }echo '</details>';}
    echo '<input name="policy_matrix_complete" type="hidden" value="'.count(domain_catalog()).'">';
}
